(()=>{
  const grid=document.querySelector('#browse-products');if(!grid)return;
  const RATE=6.6753, TTL=30*60*1000, FAIL_TTL=5*60*1000, cache=new Map(), pending=new Set(), queue=[];
  const menu=document.querySelector('.language');
  const copy={en:['Visible prices refresh from the source when available; price sorting uses the catalogue snapshot. USD conversion uses the dated rate above.','Source estimate'],zh:['可见商品在来源可用时更新价格；价格排序仍按目录快照。美元换算使用上方标明的历史汇率。','来源估价'],de:['Sichtbare Preise werden bei verfügbarer Quelle aktualisiert; die Sortierung nutzt den Katalogstand. Die USD-Umrechnung verwendet den oben angegebenen historischen Kurs.','Quellschätzung'],fr:['Les prix visibles sont actualisés lorsque la source est disponible ; le tri utilise le catalogue enregistré. La conversion USD utilise le taux daté ci-dessus.','Estimation source'],es:['Los precios visibles se actualizan cuando la fuente está disponible; el orden usa la instantánea del catálogo. La conversión USD usa el cambio indicado arriba.','Estimación de origen'],it:['I prezzi visibili si aggiornano quando la fonte è disponibile; l’ordine usa il catalogo salvato. La conversione USD usa il cambio indicato sopra.','Stima dalla fonte'],pt:['Os preços visíveis são atualizados quando a fonte está disponível; a ordenação usa o catálogo salvo. A conversão USD usa o câmbio informado acima.','Estimativa da fonte'],nl:['Zichtbare prijzen worden bijgewerkt als de bron beschikbaar is; de sortering gebruikt de catalogusopname. USD-omrekening gebruikt de bovenstaande historische koers.','Bronschatting'],pl:['Widoczne ceny są aktualizowane, gdy źródło jest dostępne; sortowanie używa zapisanej wersji katalogu. Przeliczenie USD stosuje podany wyżej historyczny kurs.','Szacunek źródła'],sv:['Synliga priser uppdateras när källan är tillgänglig; sorteringen använder katalogversionen. USD-omräkningen använder den äldre kursen ovan.','Källans uppskattning']};
  Object.assign(copy,{"fi":["Näkyvät hinnat päivittyvät lähteen ollessa saatavilla; hintajärjestys käyttää luettelon tilannekuvaa. USD-muunnos käyttää yllä mainittua päivättyä kurssia.","Lähteen arvio"],"da":["Synlige priser opdateres, når kilden er tilgængelig; prissortering bruger katalogets øjebliksbillede. USD-omregning bruger den daterede kurs ovenfor.","Kildeestimat"],"nb":["Synlige priser oppdateres når kilden er tilgjengelig; prissortering bruker katalogens øyeblikksbilde. USD-omregning bruker den daterte kursen ovenfor.","Kildeestimat"],"cs":["Viditelné ceny se aktualizují, je-li zdroj dostupný; řazení podle ceny používá uložený stav katalogu. Přepočet na USD používá výše uvedený kurz k danému datu.","Odhad ze zdroje"],"sk":["Viditeľné ceny sa aktualizujú, ak je zdroj dostupný; radenie podľa ceny používa uložený stav katalógu. Prepočet na USD používa vyššie uvedený kurz k danému dátumu.","Odhad zo zdroja"],"hu":["A látható árak a forrás elérhetősége esetén frissülnek; az ár szerinti rendezés a katalógus pillanatképét használja. Az USD-átváltás a fent megadott dátumhoz tartozó árfolyamot használja.","Forrásbecslés"],"ro":["Prețurile vizibile se actualizează când sursa este disponibilă; sortarea după preț folosește instantaneul catalogului. Conversia în USD folosește cursul datat de mai sus.","Estimare din sursă"],"el":["Οι ορατές τιμές ενημερώνονται όταν η πηγή είναι διαθέσιμη· η ταξινόμηση τιμών χρησιμοποιεί το αποθηκευμένο στιγμιότυπο καταλόγου. Η μετατροπή σε USD χρησιμοποιεί την παραπάνω ισοτιμία της συγκεκριμένης ημερομηνίας.","Εκτίμηση πηγής"],"uk":["Видимі ціни оновлюються, коли джерело доступне; сортування за ціною використовує збережений стан каталогу. Конвертація в USD використовує зазначений вище курс на відповідну дату.","Оцінка джерела"],"ar":["تُحدّث الأسعار الظاهرة عند توفر المصدر؛ ويستخدم ترتيب الأسعار نسخة الكتالوج المحفوظة. يستخدم التحويل إلى الدولار الأمريكي سعر الصرف المؤرخ أعلاه.","تقدير المصدر"],"ja":["表示価格は取得元が利用可能な場合に更新されます。価格順の並べ替えには保存されたカタログを使用します。米ドルへの換算には上記の日付の為替レートを使用します。","取得元の参考価格"],"ko":["표시 가격은 출처를 이용할 수 있을 때 업데이트되며, 가격 정렬에는 저장된 카탈로그가 사용됩니다. 미국 달러 환산에는 위에 표시된 날짜의 환율이 사용됩니다.","출처 추정가"],"vi":["Giá hiển thị được cập nhật khi nguồn sẵn có; sắp xếp theo giá dùng bản chụp danh mục. Quy đổi USD sử dụng tỷ giá có ngày nêu ở trên.","Giá ước tính từ nguồn"],"tr":["Görünür fiyatlar kaynak kullanılabilir olduğunda güncellenir; fiyat sıralaması katalog anlık görüntüsünü kullanır. USD dönüşümü yukarıda tarihli kuru kullanır.","Kaynak tahmini"]});
  const notice=document.createElement('p');notice.className='live-price-note notranslate';notice.setAttribute('translate','no');grid.before(notice);
  const locale=()=>copy[menu?.value]||copy.en;
  function label(){notice.textContent=locale()[0];grid.querySelectorAll('[data-live-price]').forEach(el=>{el.textContent=locale()[1]})}
  menu?.addEventListener('change',label);label();
  let active=0;
  async function run(){while(active<2&&queue.length){const job=queue.shift();if(!job.card.isConnected){pending.delete(job.id);continue}active++;(async()=>{try{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);let response;try{response=await fetch('https://findspreadsheet.com/api/Goods/getSkuData?weidian_id='+encodeURIComponent(job.id),{credentials:'omit',signal:controller.signal})}finally{clearTimeout(timer)}if(!response.ok)throw Error('unavailable');const d=await response.json(),price=Number(d.price);if(String(d.weidian_id)!==job.id||!Number.isFinite(price)||price<=0)throw Error('invalid source response');const images=(Array.isArray(d.images)?d.images:[]).filter(src=>{try{return new URL(src).protocol==='https:'}catch{return false}});cache.set(job.id,{price,images,until:Date.now()+TTL});}catch{cache.set(job.id,{until:Date.now()+FAIL_TTL})}finally{active--;pending.delete(job.id);grid.querySelectorAll('.product-card').forEach(card=>{const link=card.querySelector('a[href]');try{if(card.dataset.weidianId===job.id)apply(card,job.id)}catch{}});run()}})()}}
  function apply(card,id){const entry=cache.get(id);if(!entry||entry.until<Date.now()||!Number.isFinite(entry.price)||!card.isConnected)return;const img=card.querySelector('.product-image img');if(img&&entry.images?.length&&!img.dataset.sourceFallback){img.dataset.sourceFallback=entry.images[0];if(img.complete&&img.naturalWidth===0)img.src=entry.images[0];else img.addEventListener('error',()=>{if(img.src!==img.dataset.sourceFallback)img.src=img.dataset.sourceFallback},{once:true})}const price=card.querySelector('.product-bottom > span');if(!price)return;price.dataset.cnyPrice=entry.price;price.textContent=window.joyCurrency?window.joyCurrency.format(entry.price):'$'+(entry.price/RATE).toFixed(2)+' USD';let note=card.querySelector('[data-live-price]');if(!note){note=document.createElement('small');note.dataset.livePrice='';note.className='source-price-label notranslate';note.setAttribute('translate','no');price.after(note)}note.textContent=locale()[1]}
  const observer='IntersectionObserver' in window?new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;observer.unobserve(entry.target);const card=entry.target,a=card.querySelector('a[href]');let id='';try{id=card.dataset.weidianId||''}catch{}if(!/^\d+$/.test(id))return;const hit=cache.get(id);if(hit&&hit.until>Date.now()){apply(card,id);return}if(!pending.has(id)){pending.add(id);queue.push({card,id});run()}}),{rootMargin:'300px'}):null;
  function watch(){if(observer)grid.querySelectorAll('.product-card').forEach(card=>{if(!card.dataset.priceWatch){card.dataset.priceWatch='1';observer.observe(card)}})}
  new MutationObserver(watch).observe(grid,{childList:true});watch();
})();
